tool_calls:
cat > /home/eval/report.sh <<'EOF'
#!/usr/bin/env bash
# Usage: report.sh INBOX_DIR OUT_FILE
# Counts recipient addresses (to + cc) per domain across *.json messages.
inbox="${1:?usage: report.sh INBOX_DIR OUT_FILE}"
out="${2:?usage: report.sh INBOX_DIR OUT_FILE}"

python3 - "$inbox" "$out" <<'PY'
import sys, os, json
from email.utils import getaddresses
from collections import Counter

inbox, out = sys.argv[1], sys.argv[2]
counts = Counter()
try:
    names = sorted(n for n in os.listdir(inbox)
                   if n.endswith('.json') and os.path.isfile(os.path.join(inbox, n)))
except OSError:
    names = []

for name in names:
    try:
        with open(os.path.join(inbox, name), encoding='utf-8') as fh:
            msg = json.load(fh)
        if not isinstance(msg, dict):
            raise ValueError("not an object")
    except (ValueError, UnicodeDecodeError, OSError):
        print(f"skip: {name}", file=sys.stderr)
        continue
    headers = []
    for field in ("to", "cc"):
        v = msg.get(field)
        if isinstance(v, str):
            headers.append(v)
        elif isinstance(v, list):
            headers.extend(x for x in v if isinstance(x, str))
    for _, addr in getaddresses(headers):
        addr = addr.strip()
        if '@' not in addr:
            continue
        domain = addr.rsplit('@', 1)[1].strip().rstrip('>').lower()
        if domain:
            counts[domain] += 1

d = os.path.dirname(out)
if d:
    os.makedirs(d, exist_ok=True)
with open(out, 'w', encoding='utf-8') as fh:
    for dom, c in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
        fh.write(f"{c} {dom}\n")
PY
exit 0
EOF
bash /home/eval/report.sh /data/inbox /out/domains.txt; echo "exit=$?"; cat /out/domains.txt

